export function hut(): Raster {
  const img = new Raster(64, 64);
  img.rect({ x: 8, y: 28, w: 48, h: 34, color: hex('#7a4a24') });
  for (let i = 0; i < 34; i += 4) img.rect({ x: 8, y: 28 + i, w: 48, h: 1, color: hex('#5e3818') });
  for (let r = 0; r < 28; r++) {
    const half = 4 + r;
    img.rect({
      x: 32 - half,
      y: r + 2,
      w: half * 2,
      h: 1,
      color: r % 4 === 0 && r > 0 ? hex('#8a2a20') : hex('#b8392b'),
    });
  }
  img.rect({ x: 26, y: 44, w: 12, h: 18, color: hex('#2a1a10') });
  img.rect({ x: 35, y: 53, w: 1, h: 2, color: hex('#f2c230') });
  img.rect({ x: 12, y: 36, w: 8, h: 7, color: SAND });
  img.rect({ x: 44, y: 36, w: 8, h: 7, color: SAND });
  return img;
}

/**
 * The Guild Hall (§7.1, #179): Ibitsa's settings, in Home Village beside the hut. A stone hall with a
 * slate roof, a banner and a door, 48×48.
 */
export function guildHall(): Raster {
  const img = new Raster(48, 48);
  const stone = hex('#9a9a9a');
  const stoneDark = hex('#6e6e6e');
  img.rect({ x: 4, y: 20, w: 40, h: 26, color: stone });
  for (let y = 22; y < 46; y += 4) img.rect({ x: 4, y, w: 40, h: 1, color: stoneDark });
  for (let r = 0; r < 18; r++) {
    const half = 6 + r;
    img.rect({
      x: 24 - half,
      y: r + 2,
      w: half * 2,
      h: 1,
      color: r % 3 === 0 ? hex('#3a4a6a') : hex('#4a5d82'),
    });
  }
  img.rect({ x: 19, y: 32, w: 10, h: 14, color: hex('#2a1a10') });
  img.rect({ x: 26, y: 39, w: 1, h: 2, color: hex('#f2c230') });
  // The banner: Ibitsa's gold on blue, hanging from the roof's edge.
  img.rect({ x: 8, y: 22, w: 6, h: 10, color: hex('#2f5fb0') });
  img.rect({ x: 10, y: 25, w: 2, h: 3, color: hex('#f2c230') });
  img.rect({ x: 34, y: 24, w: 6, h: 5, color: SAND });
  return img;
}

/** 24×24 9-slice dialogue frame with an 8 px inset. */
export function dialogueFrame(): Raster {
  const img = new Raster(24, 24);
  img.rect({ x: 0, y: 0, w: 24, h: 24, color: INK });
  img.rect({ x: 2, y: 2, w: 20, h: 20, color: hex('#8a6a3a') });
  img.rect({ x: 3, y: 3, w: 18, h: 18, color: hex('#efe0b8') });
  for (const [x, y] of [
    [3, 3],
    [20, 3],
    [3, 20],
    [20, 20],
  ] as const)
    img.set({ x, y, color: hex('#f2c230') });
  return img;
}

/** Phaser's built-in textures, bundled so the webview needs no data: images for them (spec §13). */
export function engineTextures(): Record<string, Raster> {
  const missing = new Raster(32, 32);
  for (let y = 0; y < 32; y++) {
    for (let x = 0; x < 32; x++)
      missing.set({
        x,
        y,
        color: ((x >> 3) + (y >> 3)) % 2 === 0 ? hex('#ff00ff') : hex('#000000'),
      });
  }
  const white = new Raster(4, 4);
  white.rect({ x: 0, y: 0, w: 4, h: 4, color: hex('#ffffff') });
  const blank = new Raster(32, 32);
  blank.rect({ x: 0, y: 0, w: 32, h: 32, color: CLEAR });
  return { 'default.png': blank, 'missing.png': missing, 'white.png': white };
}

