const ICON_PALETTE = {
  o: INK,
  c: hex('#fff6dc'),
  k: INK,
  b: hex('#7a4a24'),
  w: hex('#fdfaf0'),
  g: hex('#3f9b4a'),
  s: hex('#8a8f98'),
  d: hex('#2a2f3a'),
  u: hex('#cfe3f5'),
};

/** The activity icon strip: one 12×12 badge per kind, in the order given. */
export function activityIcons(kinds: readonly (keyof typeof GLYPHS)[]): Raster {
  const size = 12;
  const img = new Raster(size * kinds.length, size);
  kinds.forEach((kind, i) => {
    img.pattern({ x: i * size, y: 0, rows: BADGE, palette: ICON_PALETTE });
    img.pattern({ x: i * size, y: 0, rows: GLYPHS[kind], palette: ICON_PALETTE });
  });
  return img;
}
